      // we must have a method (not a struct field)
      f = obj instanceof objectTypes.Func ? obj : null;
      if (f === null) {
        state = field;
        break;
      }

      // methods may not have a fully set up signature yet
      if (check !== null) {
        check.objDecl(f);
      }

      if (f.nointerface) {
        state = nointerface;
        break;
      }

      if (!equivalent(f.typ, m.typ)) {
        state = wrongSig;
        break;
      }
